async function get<T>(path:string,signal?:AbortSignal):Promise<T>{const response=await fetch(path,{signal,cache:'no-store',credentials:'same-origin'});const value=await response.json();if(!response.ok)throw new RejectedRequest(value.error??'The case evidence could not be read.',response.status);return value;}
async function post<T>(path:string,body:unknown,csrf?:string):Promise<T>{const response=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json',...(csrf?{'X-AffinityQA-CSRF':csrf}:{})},body:JSON.stringify(body),cache:'no-store',credentials:'same-origin'});const value=await response.json();if(!response.ok)throw new RejectedRequest(value.error??'The operation could not be admitted.',response.status);return value;}

