  useEffect(()=>{try{const stored=sessionStorage.getItem(selectionKey);selectedJobId.current=stored&&/^[a-zA-Z0-9_-]{1,160}$/.test(stored)?stored:null;restoredSelectionId.current=selectedJobId.current}catch{selectedJobId.current=null;restoredSelectionId.current=null}},[selectionKey]);
