  useEffect(()=>{if(job||!cap||(publicMode&&!csrf))return;const id=selectedJobId.current;if(!id)return;const controller=new AbortController();get<Job>(base+'/jobs/'+id,controller.signal).then(value=>{if(controller.signal.aborted)return;rememberJob(value);if(!uncertainOperation.current){setUncertain(false);setError('')}}).catch(e=>{if(e.name==='AbortError')return;if(e instanceof RejectedRequest&&e.status===404){selectedJobId.current=null;try{sessionStorage.removeItem(selectionKey)}catch{}setError('The selected saved case is unavailable to this session. You can still inspect the cases listed below.');return;}setUncertain(true);setError('The saved case could not be restored. Check its current status before another action.')});return()=>controller.abort()},[cap,csrf,job?.job_id,base,publicMode,rememberJob,selectionKey]);
