  useEffect(()=>{if(!pollingJob)return;const controller=new AbortController();let timer:ReturnType<typeof setTimeout>;const poll=(current:Job)=>{timer=setTimeout(()=>{get<Job>(base+'/jobs/'+current.job_id,controller.signal).then(value=>{if(selectedJobId.current===value.job_id)rememberJob(value);else setActiveCase(busy(value)?{job:value,scope:publicMode?csrf:'local'}:null);setError('');if(busy(value))poll(value);else setReload(n=>n+1)}).catch(e=>{if(e.name!=='AbortError'){if(handleMissingSession(e))return;setError('Progress is unavailable. The job may still be running; check its current status before another action.');uncertainOperation.current??={kind:'job',jobId:current.job_id};setUncertain(true);}})},pollingDelay(current,publicMode))};poll(pollingJob);return()=>{controller.abort();clearTimeout(timer)}},[pollingJob?.job_id,pollingJob?.status,pollingJob?.queue_status,pollingJob?.not_before,base,publicMode,csrf,reload,rememberJob,handleMissingSession]);
  async function action(run:()=>Promise<Job>,mutation=false,recoveryJobId?:string){if(inFlight.current)return;inFlight.current=true;setPending(true);setError('');setRecoveryNotice('');try{const value=await run();if(mounted.current){rememberJob(value);setFault(0);setRepeat(0);setReload(n=>n+1)}}catch(e){if(mounted.current){setError(e instanceof Error?e.message:'The operation failed.');if(mutation&&(!(e instanceof RejectedRequest)||e.status>=500)){uncertainOperation.current=recoveryJobId?{kind:'job',jobId:recoveryJobId}:{kind:'plan'};setUncertain(true);}}}finally{inFlight.current=false;if(mounted.current)setPending(false)}}
  async function connect(){if(inFlight.current)return;inFlight.current=true;setPending(true);setError('');try{const value=await post<{schema_version:number;csrf_token:string;expires_utc:string}>(base+'/session',{});if(value.schema_version!==1||!/^[a-f0-9]{64}$/.test(value.csrf_token))throw Error('Session response could not be verified.');if(mounted.current){setCap(null);setCsrf(value.csrf_token);setUncertain(uncertainOperation.current!==null);}}catch(e){if(mounted.current)setError(e instanceof Error?e.message:'Session access unavailable.')}finally{inFlight.current=false;if(mounted.current)setPending(false)}}
  async function checkStatus(){if(inFlight.current)return;inFlight.current=true;setPending(true);try{if(publicMode&&!csrf){setReload(n=>n+1);return;}let value:Capability;try{value=await get<Capability>(base+'/capabilities');}catch(e){if(mounted.current&&handleMissingSession(e))return;throw e;}const unresolved=uncertainOperation.current;const selectedId=unresolved?.kind==='job'?unresolved.jobId:unresolved?.kind==='plan'?null:job&&(canAccessJob||value.jobs.some(item=>item.job_id===job.job_id))?job.job_id:selectedJobId.current??value.jobs.at(-1)?.job_id;const latest=selectedId?await get<Job>(base+'/jobs/'+selectedId):null;if(mounted.current){setCap(previous=>({...value,jobs:mergeSavedJobs(value.jobs,previous?.jobs??[])}));if(latest)rememberJob(latest);uncertainOperation.current=null;setUncertain(false);setError('');setRecoveryNotice(unresolved?.kind==='plan'?'Saved plans have been refreshed. Inspect your saved cases below before preparing another plan. The uncertain plan request was not repeated.':'');setReload(n=>n+1);}}catch(e){if(mounted.current)setError(e instanceof Error?e.message:'Status unavailable.')}finally{inFlight.current=false;if(mounted.current)setPending(false)}}
  async function loadEarlierCases(){const cursor=cap?.next_cursor_job_id;if(!publicMode||!csrf||!cursor||inFlight.current)return;inFlight.current=true;setPending(true);setError('');try{const value=await get<SavedJobPage>(base+'/jobs/older-than/'+encodeURIComponent(cursor));if(value.schema_version!==1||!Array.isArray(value.jobs))throw Error('Earlier-case response could not be verified.');if(mounted.current)setCap(previous=>previous?{...previous,jobs:mergeSavedJobs(previous.jobs,value.jobs),jobs_truncated:value.jobs_truncated,next_cursor_job_id:value.next_cursor_job_id}:previous);}catch(e){if(mounted.current)setError(e instanceof Error?e.message:'Earlier saved cases could not be read.')}finally{inFlight.current=false;if(mounted.current)setPending(false)}}
  const cinemaEnabled=cinemaMode&&cap?.cinema_preferences_supported===true;
