  const discoveryEnabled=identityEnabled&&cap?.cinema_discoveries_supported===true;
  const fastPairEnabled=discoveryEnabled&&cap?.fast_pair_review_supported===true;
  const expectedModelDecisions=cinemaEnabled?(fastPairEnabled?1:2):39;
  const movieInputEnabled=discoveryEnabled&&cap?.movie_input_search_supported===true&&cap?.maximum_movie_queries_per_case===2;
  const pairedJob=job?.case_protocol==='cinema-paired-discovery-v1';
  const movieInputJob=job?.case_protocol==='cinema-confirmed-discovery-v4'||pairedJob&&!!job?.movie_queries&&movieQueryCount(job.movie_queries)>0;
  const activeMovieQueries=movieInputEnabled?movieQueries:emptyMovieQueries();
  const normalizedMovieQueries:MovieQueryPair={A:activeMovieQueries.A.map(query=>query.normalize('NFKC').trim().replace(/\s+/gu,' ')),B:activeMovieQueries.B.map(query=>query.normalize('NFKC').trim().replace(/\s+/gu,' '))};
  const validMovieQueries=movieQueryCount(normalizedMovieQueries)<=2&&(['A','B'] as const).every(profile=>normalizedMovieQueries[profile].every(query=>Array.from(query).length>0&&Array.from(query).length<=200)&&new Set(normalizedMovieQueries[profile].map(query=>query.toLocaleLowerCase('und'))).size===normalizedMovieQueries[profile].length);
